using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
namespace PZ3D {
 static class ManagedBackgroundWorkerTests {
  static string Prepare(string source,string key){var type=typeof(CoreFixture).Assembly.GetType("PZ3D.ManagedBackgroundWorker");if(type==null)throw new Exception("FAIL: authenticated monitor image preparation exists");var m=type.GetMethod("Prepare",BindingFlags.NonPublic|BindingFlags.Static);if(m==null)throw new Exception("FAIL: fixture can prepare authenticated image internally");try{return (string)m.Invoke(null,new object[]{source,key});}catch(TargetInvocationException e){throw e.InnerException;}}
  static string Install(){string root=CoreFixture.Root();var files=new Dictionary<string,byte[]>{{"橙子启动器.exe",File.ReadAllBytes(typeof(CoreFixture).Assembly.Location)},{"Web/app.js",CoreFixture.Bytes("fixture")}};CoreDeployment.Install(root,CoreFixture.Manifest("1.2.3",files),files,CoreFixture.Key);return root;}
  static string Image(string root){return Path.Combine(root,"橙子启动器.exe");}
  public static int Main(string[] args){try{
   if(args.Length==3&&(args[0]=="--playtime-watch"||args[0]=="--session-watch")){File.WriteAllText(Path.Combine(Environment.CurrentDirectory,args[0]+".ready"),args[1]+"\n"+args[2]);Thread.Sleep(60000);return 0;}
   if(args.Length==1&&args[0]=="--fixture-launch"){string root=AppDomain.CurrentDomain.BaseDirectory;var start=typeof(CoreFixture).Assembly.GetType("PZ3D.ManagedBackgroundWorker").GetMethod("Start",BindingFlags.Static|BindingFlags.NonPublic);foreach(string role in new[]{"--playtime-watch","--session-watch"})using(var worker=(Process)start.Invoke(null,new object[]{role,role=="--playtime-watch"?Path.Combine(root,"fixture data"):new string('A',64),new string('a',32)}))File.AppendAllText(Path.Combine(root,"worker-pids"),worker.Id+"\n");return 0;}
   CoreFixture.Initialize();Run();Console.WriteLine("MANAGED BACKGROUND WORKERS: "+CoreFixture.Passed+" PASS");return 0;
  }catch(Exception e){Console.WriteLine(e);return 1;}}
  static void Run(){
   string root=Install(),source=Image(root),hash=CoreReleaseProtocol.HashFile(source),cached=Prepare(source,CoreFixture.Key);CoreFixture.Check(cached==Path.Combine(root,"OrangeLauncherRuntime","BackgroundWorkers",hash.ToLowerInvariant(),"橙子启动器.exe")&&CoreReleaseProtocol.HashFile(cached)==hash,"signed launcher is prepared under immutable hash runtime path");
   CoreFixture.Check(Prepare(source,CoreFixture.Key)==cached,"repeated preparation reuses verified image");
   string unknown=Path.Combine(root,"other.exe");File.Copy(source,unknown);CoreFixture.Reject(()=>Prepare(unknown,CoreFixture.Key),"unknown source image rejected");
   CoreFixture.Reject(()=>Prepare(source,null),"explicit managed record cannot fall back without trust key");
   File.AppendAllText(source,"changed");CoreFixture.Reject(()=>Prepare(source,CoreFixture.Key),"modified source rejected even with valid cache");
   root=Install();source=Image(root);cached=Prepare(source,CoreFixture.Key);File.AppendAllText(cached,"changed");CoreFixture.Reject(()=>Prepare(source,CoreFixture.Key),"modified existing runtime image rejected without overwrite");
   root=Install();source=Image(root);string record=Path.Combine(root,CoreDeployment.RecordName);File.WriteAllText(record,File.ReadAllText(record).Replace("\"version\":\"1.2.3\"","\"version\":\"1.2.4\""));CoreFixture.Reject(()=>Prepare(source,CoreFixture.Key),"unsigned installation record mismatch rejects preparation");
   root=Install();source=Image(root);using(CoreDeployment.Acquire(root)){var attempt=Task.Run(()=>{CoreFixture.Reject(()=>Prepare(source,CoreFixture.Key),"concurrent conflicting root transaction rejects preparation");});attempt.Wait();}
   string first=Prepare(source,CoreFixture.Key),second=null;Task.Run(()=>second=Prepare(source,CoreFixture.Key)).Wait();CoreFixture.Check(first==second,"separate preparation thread reuses same verified immutable image");
   WrongTypeEvidence();ConcurrentPreparation();Reparse(false);Reparse(true);Lifecycle();SignedStart();Lowercase();
   var type=typeof(CoreFixture).Assembly.GetType("PZ3D.ManagedBackgroundWorker");var start=type.GetMethod("Start",BindingFlags.Static|BindingFlags.NonPublic);foreach(string role in new[]{"--shell","--core-apply"})CoreFixture.Reject(()=>start.Invoke(null,new object[]{role,"x",new string('a',32)}),"arbitrary worker role rejected");foreach(string[] args in new[]{new[]{"--session-watch","bad",new string('a',32)},new[]{"--playtime-watch","relative",new string('a',32)},new[]{"--playtime-watch","C:\\safe\" --shell",new string('a',32)},new[]{"--session-watch",new string('A',64),"bad"}})CoreFixture.Reject(()=>start.Invoke(null,args.Cast<object>().ToArray()),"worker identity and argument injection rejected");
   string legacy=Path.Combine(CoreFixture.Root(),"old.exe");Directory.CreateDirectory(Path.GetDirectoryName(legacy));File.Copy(typeof(CoreFixture).Assembly.Location,legacy);CoreFixture.Check(Prepare(legacy,null)==legacy,"untrusted single EXE retains original image behavior");
  }
  static void WrongTypeEvidence(){var accepted=new List<string>();foreach(string artifact in new[]{CoreDeployment.Owner,CoreDeployment.Runtime+"/CoreBootstrap"}){string root=CoreFixture.Root(),source=Image(root),path=CoreFixture.FileAt(root,artifact);Directory.CreateDirectory(Path.GetDirectoryName(path));File.Copy(typeof(CoreFixture).Assembly.Location,source);if(artifact==CoreDeployment.Owner)Directory.CreateDirectory(path);else File.WriteAllText(path,"malformed bootstrap metadata");bool rejected=false;try{Prepare(source,null);}catch(IOException){rejected=true;}Console.WriteLine("Wrong-type trust evidence "+artifact+": rejected="+rejected);if(!rejected)accepted.Add(artifact);}CoreFixture.Check(accepted.Count==0,"wrong-type owner directory and bootstrap file cannot downgrade to legacy: "+string.Join(", ",accepted));}
  static void ConcurrentPreparation(){string root=Install(),source=Image(root);using(var begin=new ManualResetEventSlim()){var jobs=Enumerable.Range(0,4).Select(i=>Task.Run(()=>{begin.Wait();for(int attempt=0;;attempt++){try{return Prepare(source,CoreFixture.Key);}catch(IOException e){if(attempt>=50||!e.Message.Contains("Another process owns"))throw;Thread.Sleep(20);}}})).ToArray();begin.Set();Task.WaitAll(jobs);CoreFixture.Check(jobs.Select(j=>j.Result).Distinct().Count()==1&&Directory.GetFiles(Path.Combine(root,CoreDeployment.Runtime,"BackgroundWorkers"),"*.exe",SearchOption.AllDirectories).Length==1,"simultaneous preparations converge on one verified immutable worker image");}}
  static void Lowercase(){string root=CoreFixture.Root();var files=new Dictionary<string,byte[]>{{"橙子启动器.exe",File.ReadAllBytes(typeof(CoreFixture).Assembly.Location)}};var manifest=CoreFixture.Manifest("1.2.3",files);string raw=CoreDeployment.Utf8.GetString(manifest.VerifiedEnvelope.Raw);foreach(var file in manifest.files)raw=raw.Replace(file.sha256,file.sha256.ToLowerInvariant());byte[] bytes=CoreFixture.Bytes(raw);var lower=CoreReleaseProtocol.Verify(bytes,CoreFixture.Signer.SignData(bytes,CryptoConfig.MapNameToOID("SHA256")),CoreFixture.Key,"0.0.0");CoreDeployment.Install(root,lower,files,CoreFixture.Key);CoreFixture.Check(File.Exists(Prepare(Image(root),CoreFixture.Key)),"valid signed lowercase SHA256 accepted");}
  static void SignedStart(){
   string build=CoreFixture.Root(),key=Path.Combine(build,"fixture-public.xml"),compiled=Path.Combine(build,"fixture.exe"),repository=Path.GetDirectoryName(AppDomain.CurrentDomain.BaseDirectory.TrimEnd(Path.DirectorySeparatorChar)),project=Path.Combine(repository,"Orange3DTool"),sdk=Path.Combine(repository,"Dependencies","WebView2","lib","net462");Directory.CreateDirectory(build);File.WriteAllText(key,CoreFixture.Key);
   string arguments="/nologo /target:exe /main:PZ3D.ManagedBackgroundWorkerTests /out:\""+compiled+"\" /resource:\""+key+"\",Launcher.UpdatePublicKey.xml /reference:System.Windows.Forms.dll /reference:System.Drawing.dll /reference:System.Web.Extensions.dll /reference:System.Management.dll /reference:System.IO.Compression.dll /reference:System.IO.Compression.FileSystem.dll /reference:System.Security.dll /reference:\""+Path.Combine(sdk,"Microsoft.Web.WebView2.Core.dll")+"\" /reference:\""+Path.Combine(sdk,"Microsoft.Web.WebView2.WinForms.dll")+"\" "+string.Join(" ",Directory.GetFiles(project,"*.cs").Select(p=>"\""+p+"\""));
   using(var compiler=Process.Start(new ProcessStartInfo(Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"Microsoft.NET","Framework64","v4.0.30319","csc.exe"),arguments){UseShellExecute=false,CreateNoWindow=true})){CoreFixture.Check(compiler.WaitForExit(30000)&&compiler.ExitCode==0,"ephemeral-key compiled fixture built");}
   string root=CoreFixture.Root();var files=new Dictionary<string,byte[]>{{"橙子启动器.exe",File.ReadAllBytes(compiled)}};CoreDeployment.Install(root,CoreFixture.Manifest("1.2.3",files),files,CoreFixture.Key);var workers=new List<Process>();
   try{using(var launcher=Process.Start(new ProcessStartInfo(Image(root),"--fixture-launch"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root})){CoreFixture.Check(launcher.WaitForExit(10000)&&launcher.ExitCode==0,"production Start launches both authenticated worker roles");}
    foreach(string pid in File.ReadAllLines(Path.Combine(root,"worker-pids")))workers.Add(Process.GetProcessById(int.Parse(pid)));
    string cached=Prepare(Image(root),CoreFixture.Key),hash=CoreReleaseProtocol.HashFile(cached);CoreFixture.Check(workers.Count==2&&workers.All(p=>!p.HasExited&&CoreDeployment.SamePath(p.MainModule.FileName,cached)),"both actual Start worker PIDs execute authenticated runtime image");
    var end=DateTime.UtcNow.AddSeconds(5);while((!File.Exists(Path.Combine(root,"--playtime-watch.ready"))||!File.Exists(Path.Combine(root,"--session-watch.ready")))&&DateTime.UtcNow<end)Thread.Sleep(20);
    CoreFixture.Check(File.ReadAllText(Path.Combine(root,"--playtime-watch.ready"))==Path.Combine(root,"fixture data")+"\n"+new string('a',32)&&File.ReadAllText(Path.Combine(root,"--session-watch.ready"))==new string('A',64)+"\n"+new string('a',32),"worker launch preserves exact role arguments including spaces");
    string replacement=Image(root)+".next";File.WriteAllText(replacement,"next root launcher");File.Replace(replacement,Image(root),null);CoreFixture.Check(workers.All(p=>!p.HasExited)&&CoreReleaseProtocol.HashFile(cached)==hash,"authenticated Start workers survive root launcher replacement");
   }finally{foreach(var worker in workers){if(!worker.HasExited){worker.Kill();worker.WaitForExit(5000);}worker.Dispose();}}
  }
  static void Reparse(bool runtime){string root=Install(),source=Image(root),outside=CoreFixture.Root();Directory.CreateDirectory(outside);string link=runtime?Path.Combine(root,"OrangeLauncherRuntime","BackgroundWorkers"):Path.Combine(root,"source-link");using(var cmd=Process.Start(new ProcessStartInfo("cmd.exe","/c mklink /J \""+link+"\" \""+(runtime?outside:root)+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true})){cmd.WaitForExit();CoreFixture.Check(cmd.ExitCode==0,"fixture junction created");}CoreFixture.Reject(()=>Prepare(runtime?source:Path.Combine(link,"橙子启动器.exe"),CoreFixture.Key),runtime?"runtime junction rejected":"source junction rejected");Directory.Delete(link);}
  static void Lifecycle(){string root=Install(),source=Image(root),cached=Prepare(source,CoreFixture.Key),hash=CoreReleaseProtocol.HashFile(cached),data=Path.Combine(root,"data"),user=Path.Combine(root,"user");Directory.CreateDirectory(user);File.WriteAllText(Path.Combine(user,"default.txt"),"temporary-list");Directory.CreateDirectory(Path.Combine(data,"launch-sessions"));File.WriteAllText(Path.Combine(data,"launch-sessions","pending.json"),"pending");DateTime now=DateTime.UtcNow;PlaytimeTracker.Sample(data,"fixture",now,true);PlaytimeTracker.Sample(data,"fixture",now.AddSeconds(5),true);string totals=File.ReadAllText(Path.Combine(data,"playtime","time.json"));
   var processes=new List<Process>();try{foreach(string role in new[]{"--playtime-watch","--session-watch"})processes.Add(Process.Start(new ProcessStartInfo(cached,role+" fixture fixture"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root}));string game=Path.Combine(root,"fixture-game.exe");File.Copy(cached,game);processes.Add(Process.Start(new ProcessStartInfo(game,"--playtime-watch fixture fixture"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=root}));Thread.Sleep(300);string replacement=source+".next";File.WriteAllText(replacement,"replacement root image");File.Replace(replacement,source,null);CoreFixture.Check(processes.All(p=>!p.HasExited),"both workers and separate fixture game remain alive during root image replacement");CoreFixture.Check(CoreReleaseProtocol.HashFile(cached)==hash,"running immutable image unchanged by root replacement");CoreFixture.Check(File.ReadAllText(Path.Combine(data,"playtime","time.json"))==totals&&File.ReadAllText(Path.Combine(user,"default.txt"))=="temporary-list"&&File.Exists(Path.Combine(data,"launch-sessions","pending.json")),"root replacement never resets time or restores pending launch list");}finally{foreach(var process in processes){if(!process.HasExited){process.Kill();process.WaitForExit(5000);}process.Dispose();}}
  }
 }
}
